/*
 * A328996  Numbers with at least three digits such that the absolute
 *          differences between successive digits forms a palindrome without
 *          leading zeros.
 * https://oeis.org/A328996
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the nth integer ≥100 whose successive absolute digit *
 *            differences form a palindrome with no leading zeros. The values
 *            are * generated by brute‑force enumeration and cached
 * Range:     u8 n <= 21, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function returns the n-th term of OEIS A328996. */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* Test whether a number satisfies the defining property. */
static bool is_valid(seq_t x)
{
    if (x < 100) return false;                /* need at least 3 digits */
    int digits[32];
    size_t len = 0;
    seq_t t = x;
    while (t > 0) {
        digits[len++] = (int)(t % 10);
        t /= 10;
    }
    if (len < 3) return false;                /* should not happen */
    int diff_len = (int)len - 1;              /* number of consecutive differences */

    /* First difference (most significant side) must be non‑zero */
    int first_diff = digits[len - 1] - digits[len - 2];
    if (first_diff < 0) first_diff = -first_diff;
    if (first_diff == 0) return false;

    /* Check palindrome of differences */
    for (int i = 0; i < diff_len; ++i) {
        int a = digits[len - 1 - i];
        int b = digits[len - 2 - i];
        int diff_left = a - b;
        if (diff_left < 0) diff_left = -diff_left;

        int c = digits[i + 1];
        int d = digits[i];
        int diff_right = c - d;
        if (diff_right < 0) diff_right = -diff_right;

        if (diff_left != diff_right) return false;
    }
    return true;
}

/* Cache for already generated terms */
static seq_t *cache      = NULL;
static size_t cache_cap  = 0;
static size_t cache_len  = 0;
static seq_t next_candidate = 100;
static bool initialized = false;

seq_t a(idx_t n)
{
    if (!initialized) {
        cache_cap = 1024;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
        cache_len = 0;
        next_candidate = 100;
        initialized = true;
    }

    size_t target = (size_t)n;
    while (cache_len < target) {
        seq_t val = next_candidate;
        ++next_candidate;
        if (is_valid(val)) {
            if (cache_len == cache_cap) {
                cache_cap *= 2;
                seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                if (tmp) cache = tmp;
            }
            cache[cache_len++] = val;
        }
    }
    return cache[target - 1];
}
